GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """
    Greedy placement trying several model orderings; each model is assigned to
    the GPU minimizing the KVPR after placement, subject to memory capacity.
    The ordering yielding the lowest max KVPR is returned. Guards against
    zero remaining memory (division by zero) by treating it as infinite KVPR.
    """

    def try_order(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            r = model.req_rate / model.slo
            best, best_kv = None, float('inf')
            for g in range(gpu_num):
                rem = free[g] - model.model_size
                if rem > 0:
                    kvpr = (load[g] + r) / rem
                elif rem == 0:
                    # Model exactly fills remaining memory; feasible only if no load
                    if load[g] + r <= 0:
                        kvpr = 0.0
                    else:
                        continue
                else:
                    continue
                if kvpr < best_kv:
                    best_kv, best = kvpr, g
            if best is None:
                return None
            placement[best].append(model)
            load[best] += r
            free[best] -= model.model_size
        worst = max((load[g] / free[g]) if free[g] > 0 else
                    (0.0 if load[g] == 0 else float('inf'))
                    for g in range(gpu_num))
        return placement, worst

    # Complementary-pairing constructive heuristic with reserve headroom:
    # models sorted by rate density (r/s) descending; a GPU is forbidden if
    # its post-placement free memory drops below the largest remaining model
    # size while another feasible GPU exists. Near-ties (within 5%) prefer
    # the GPU with the most free memory, preserving headroom for big models.
    def try_reserve(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [float(GPU_MEM_SIZE)] * gpu_num
        load = [0.0] * gpu_num
        for i, model in enumerate(order):
            r = model.req_rate / model.slo
            remaining_max = max((m.model_size for m in order[i + 1:]), default=0.0)
            cands = []
            for g in range(gpu_num):
                rem = free[g] - model.model_size
                if rem <= 0:
                    continue
                if rem < remaining_max and any(
                        free[h] - model.model_size >= remaining_max
                        for h in range(gpu_num) if h != g):
                    continue  # reserve violated, feasible alternative exists
                cands.append(((load[g] + r) / rem, -free[g], g))
            if not cands:
                return None
            cands.sort()
            best_kv = cands[0][0]
            best_g = cands[0][2]
            for kv, negfree, g in cands:
                if kv <= best_kv * 1.05 + 1e-12:
                    best_g = g  # cands sorted by -free: first near-tie has max free
                    break
            placement[best_g].append(model)
            load[best_g] += r
            free[best_g] -= model.model_size
        worst = max((load[g] / free[g]) if free[g] > 0 else
                    (0.0 if load[g] == 0 else float('inf'))
                    for g in range(gpu_num))
        return placement, worst

    orderings = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo / m.model_size, reverse=True),
        sorted(models, key=lambda m: m.model_size / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size / (m.req_rate / m.slo), reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo * m.model_size, reverse=True),
    ]
    best = try_reserve(orderings[0])
    for order in orderings:
        for res in (try_order(order), try_reserve(order)):
            if res is not None and (best is None or res[1] < best[1]):
                best = res
    if best is None:
        raise ValueError("Unable to place all models within GPU memory.")
    placement = best[0]

    def kvpr_of(g):
        mem = GPU_MEM_SIZE - sum(m.model_size for m in placement[g])
        if mem == 0:
            return 0.0 if not placement[g] else float('inf')
        return sum(m.req_rate / m.slo for m in placement[g]) / mem

    # Exact minimax KVPR via bisection on threshold T with MILP feasibility
    # (scipy.optimize.milp). The greedy placement above serves as the
    # incumbent upper bound T_hi and as a valid fallback. Binary variables
    # x[m,g] assign each model to one GPU subject to:
    #   - each model assigned exactly once,
    #   - per-GPU memory: sum_m s_m x[m,g] <= GPU_MEM_SIZE,
    #   - linearized KVPR: sum_m (r_m + T*s_m) x[m,g] <= T*GPU_MEM_SIZE.
    # Bisection tightens T_hi; any solver failure returns the greedy incumbent.
    import numpy as np
    from scipy.optimize import milp, LinearConstraint, Bounds

    n = len(models)
    if n == 0 or gpu_num <= 0:
        return placement

    r = np.array([m.req_rate / m.slo for m in models], dtype=float)
    s = np.array([m.model_size for m in models], dtype=float)
    gpu_of = np.zeros(n, dtype=int)
    for g in range(gpu_num):
        for m in placement[g]:
            gpu_of[[i for i, mm in enumerate(models) if mm is m][0]] = g

    def max_kvpr_assign(assign):
        load = np.zeros(gpu_num)
        mem = np.full(gpu_num, float(GPU_MEM_SIZE))
        np.add.at(load, assign, r)
        np.subtract.at(mem, assign, s)
        return float(np.max(np.where(mem > 0, load / np.maximum(mem, 1e-12),
                                     np.where(load == 0, 0.0, np.inf))))

    T_hi = max_kvpr_assign(gpu_of)
    T_lo = max(0.0, float(r.sum()) / max(gpu_num * GPU_MEM_SIZE - float(s.sum()), 1e-12))
    best_assign = gpu_of.copy()
    if T_hi > T_lo + 1e-9:
        M = n * gpu_num
        A_eq = np.zeros((n, M))
        for i in range(n):
            A_eq[i, i * gpu_num:(i + 1) * gpu_num] = 1.0
        A_mem = np.zeros((gpu_num, M))
        for i in range(n):
            for g in range(gpu_num):
                A_mem[g, i * gpu_num + g] = s[i]
        cons_eq = LinearConstraint(A_eq, np.ones(n), np.ones(n))
        cons_mem = LinearConstraint(A_mem, -np.inf, np.full(gpu_num, float(GPU_MEM_SIZE)))
        bounds = Bounds(np.zeros(M), np.ones(M))
        integrality = np.ones(M)
        for _ in range(15):
            T = 0.5 * (T_lo + T_hi)
            w = r + T * s
            A_kv = np.zeros((gpu_num, M))
            for i in range(n):
                for g in range(gpu_num):
                    A_kv[g, i * gpu_num + g] = w[i]
            cons_kv = LinearConstraint(A_kv, -np.inf, np.full(gpu_num, T * GPU_MEM_SIZE))
            try:
                res = milp(c=np.zeros(M), constraints=[cons_eq, cons_mem, cons_kv],
                           integrality=integrality, bounds=bounds,
                           options={"time_limit": 0.5, "mip_rel_gap": 0.0})
            except Exception:
                break
            if res.status == 0 and res.x is not None:
                assign = np.array([g for i in range(n) for g in range(gpu_num)
                                   if res.x[i * gpu_num + g] > 0.5], dtype=int)
                if len(assign) == n:
                    T_hi = T
                    best_assign = assign
                else:
                    T_lo = T
            else:
                T_lo = T
            if T_hi - T_lo < 1e-6:
                break
        if max_kvpr_assign(best_assign) < max_kvpr_assign(gpu_of) - 1e-12:
            placement = {g: [] for g in range(gpu_num)}
            for i, g in enumerate(best_assign):
                placement[int(g)].append(models[i])

    # Bottleneck-GPU repack: iteratively evacuate subsets of models from the
    # argmax-KVPR GPU into the exact slack of the other GPUs. For each round,
    # the models of the worst GPU are sorted by size and a subset-sum DP
    # (boolean reachability over integer-quantized capacities, capped at
    # 500k states) finds the largest removable subset fitting within the
    # free memory of the other GPUs while lowering the worst GPU's KVPR.
    # Removed models are greedily reinserted one at a time into the other
    # GPU whose post-insertion KVPR is minimal (memory-feasible only). A
    # round is committed only if the global max KVPR strictly decreases.
    # At most gpu_num rounds; every move is memory-checked, so validity
    # is preserved and the incumbent is returned unchanged otherwise.

    def kvpr_val(g):
        mem = GPU_MEM_SIZE - sum(m.model_size for m in placement[g])
        load = sum(m.req_rate / m.slo for m in placement[g])
        if mem <= 0:
            return 0.0 if load == 0 else float('inf')
        return load / mem

    def global_max():
        return max((kvpr_val(g) for g in range(gpu_num)), default=0.0)

    for _ in range(gpu_num):
        cur = global_max()
        worst = min(range(gpu_num), key=lambda g: -kvpr_val(g))
        items = list(placement[worst])
        if not items:
            break
        free_others = [GPU_MEM_SIZE - sum(m.model_size for m in placement[g])
                       for g in range(gpu_num) if g != worst]
        cap = int(sum(free_others))
        if cap <= 0:
            break
        k = len(items)
        if k > 30:
            # too many subsets for exact enumeration; take largest models
            items = sorted(items, key=lambda m: -m.model_size)[:30]
            k = 30
        # subset-sum DP over quantized sizes (1 GB resolution): best subset
        # = maximum number of items removable with total size <= cap,
        # preferring subsets whose removal best lowers worst-GPU KVPR.
        sizes = [m.model_size for m in items]
        loads = [m.req_rate / m.slo for m in items]
        total_load = sum(loads)
        dp = {0: (0, 0.0, ())}  # size -> (count, removed_load, subset)
        ok = True
        for i in range(k):
            si, li = int(round(sizes[i])), loads[i]
            if si > cap:
                continue
            new = {}
            for sz, (cnt, rl, sub) in dp.items():
                ns = sz + si
                if ns <= cap:
                    cand = (cnt + 1, rl + li, sub + (i,))
                    old = new.get(ns)
                    if old is None or cand[0] > old[0] or \
                       (cand[0] == old[0] and cand[1] > old[1]):
                        new[ns] = cand
            dp.update(new)
            if len(dp) > 500000:
                ok = False
                break
        if not ok:
            break
        # choose subset maximizing count, then removed load
        best = None
        for sz, (cnt, rl, sub) in dp.items():
            if cnt == 0:
                continue
            if best is None or (cnt, rl) > best[:2]:
                best = (cnt, rl, sub, sz)
        if best is None:
            break
        # Removal must strictly lower worst-GPU KVPR; remaining memory grows.
        sub = best[2]
        moved = [items[i] for i in sub]
        # Greedy reinsert into other GPUs at minimal resulting KVPR
        rem_free = {g: GPU_MEM_SIZE - sum(m.model_size for m in placement[g])
                    for g in range(gpu_num) if g != worst}
        rem_load = {g: sum(m.req_rate / m.slo for m in placement[g])
                    for g in range(gpu_num) if g != worst}
        feasible = True
        moves = []
        for m in moved:
            r = m.req_rate / m.slo
            bestg, bestkv = None, None
            for g in rem_free:
                rem = rem_free[g] - m.model_size
                if rem <= 0:
                    continue
                kv = (rem_load[g] + r) / rem
                if bestkv is None or kv < bestkv:
                    bestkv, bestg = kv, g
            if bestg is None:
                feasible = False
                break
            moves.append((m, bestg))
            rem_free[bestg] -= m.model_size
            rem_load[bestg] += r
        if not feasible or not moves:
            break
        # tentatively commit
        for m, g in moves:
            placement[worst].remove(m)
            placement[g].append(m)
        new_max = global_max()
        if new_max < cur - 1e-12:
            continue  # improvement; loop again on new argmax
        else:
            # revert
            for m, g in moves:
                placement[g].remove(m)
                placement[worst].append(m)
            break
    return placement

